# -*- coding: utf-8 -*-
# Alimov 9, proof tasks 50–80. 321(2) restored from scan (ctg α); wrong keys fixed: УКГ3 324(2), 326(3). Unchanged: 50, 54, 56, 57, 65, 76, 79, 80.
P = {'G9_TB_26_304_2': {'k': '$\\dfrac{\\sin 2\\alpha - 2\\cos\\alpha}{\\sin\\alpha - \\sin^{2}\\alpha} = \\dfrac{2\\cos\\alpha(\\sin\\alpha - 1)}{\\sin\\alpha(1 - \\sin\\alpha)} = -\\dfrac{2\\cos\\alpha}{\\sin\\alpha} = -2\\operatorname{ctg}\\alpha$.', 'd': [('$\\dfrac{2\\cos\\alpha(\\sin\\alpha - 1)}{\\sin\\alpha(1 - \\sin\\alpha)} = \\dfrac{2\\cos\\alpha}{\\sin\\alpha} = 2\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\sin\\alpha - 1 = -(1 - \\sin\\alpha)$: после сокращения остаётся знак «−».'), ('$\\sin\\alpha - \\sin^{2}\\alpha = \\sin\\alpha(1 + \\sin\\alpha)$, поэтому дробь не сокращается, поэтому тождество неверно.', '$\\sin\\alpha - \\sin^{2}\\alpha = \\sin\\alpha(1 - \\sin\\alpha)$.'), ('$\\sin 2\\alpha = 2\\sin\\alpha$, поэтому числитель равен $2(\\sin\\alpha - \\cos\\alpha)$, и дробь не равна $-2\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\sin 2\\alpha = 2\\sin\\alpha\\cos\\alpha$.')]}, 'G9_TB_26_304_3': {'k': '$1 + \\cos 2\\alpha = 2\\cos^{2}\\alpha$, поэтому $\\operatorname{tg}\\alpha(1 + \\cos 2\\alpha) = \\dfrac{\\sin\\alpha}{\\cos\\alpha} \\cdot 2\\cos^{2}\\alpha = 2\\sin\\alpha\\cos\\alpha = \\sin 2\\alpha$.', 'd': [('$1 + \\cos 2\\alpha = 2\\sin^{2}\\alpha$, поэтому левая часть равна $\\dfrac{2\\sin^{3}\\alpha}{\\cos\\alpha}$, поэтому тождество неверно.', '$1 + \\cos 2\\alpha = 2\\cos^{2}\\alpha$, а $2\\sin^{2}\\alpha = 1 - \\cos 2\\alpha$.'), ('$\\operatorname{tg}\\alpha(1 + \\cos 2\\alpha) = \\dfrac{\\sin\\alpha}{\\cos\\alpha} \\cdot 2\\cos^{2}\\alpha = 2\\sin\\alpha\\cos\\alpha$, а $\\sin 2\\alpha = 2\\sin\\alpha$, поэтому тождество неверно.', '$\\sin 2\\alpha = 2\\sin\\alpha\\cos\\alpha$ — это и есть полученное выражение.'), ('$\\operatorname{tg}\\alpha(1 + \\cos 2\\alpha) = \\operatorname{tg}\\alpha + \\operatorname{tg} 2\\alpha$, поэтому тождество неверно.', 'Произведение $\\operatorname{tg}\\alpha \\cdot \\cos 2\\alpha$ не равно $\\operatorname{tg} 2\\alpha$.')]}, 'G9_TB_26_304_4': {'k': '$1 - \\cos 2\\alpha + \\sin 2\\alpha = 2\\sin\\alpha(\\sin\\alpha + \\cos\\alpha)$ и $1 + \\cos 2\\alpha + \\sin 2\\alpha = 2\\cos\\alpha(\\cos\\alpha + \\sin\\alpha)$, поэтому дробь равна $\\operatorname{tg}\\alpha$, а $\\operatorname{tg}\\alpha \\cdot \\operatorname{ctg}\\alpha = 1$.', 'd': [('Числитель равен $2\\cos\\alpha(\\cos\\alpha + \\sin\\alpha)$, знаменатель $2\\sin\\alpha(\\sin\\alpha + \\cos\\alpha)$, поэтому левая часть равна $\\operatorname{ctg}^{2}\\alpha$, поэтому тождество неверно.', '$1 - \\cos 2\\alpha = 2\\sin^{2}\\alpha$ и $1 + \\cos 2\\alpha = 2\\cos^{2}\\alpha$: формулы перепутаны.'), ('$\\dfrac{1 - \\cos 2\\alpha + \\sin 2\\alpha}{1 + \\cos 2\\alpha + \\sin 2\\alpha} = \\dfrac{-\\cos 2\\alpha}{\\cos 2\\alpha} = -1$, поэтому левая часть равна $-\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', 'Одинаковые слагаемые числителя и знаменателя сокращать нельзя; сокращаются только общие множители.'), ('Дробь равна $\\operatorname{tg}\\alpha$, поэтому левая часть равна $\\operatorname{tg}^{2}\\alpha$, поэтому тождество неверно.', 'Дробь умножается на $\\operatorname{ctg}\\alpha = \\dfrac{1}{\\operatorname{tg}\\alpha}$, и произведение равно $1$.')]}, 'G9_TB_27_316_1': {'k': '$\\sin\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = \\sin\\dfrac{\\pi}{2}\\cos\\alpha + \\cos\\dfrac{\\pi}{2}\\sin\\alpha = 1 \\cdot \\cos\\alpha + 0 \\cdot \\sin\\alpha = \\cos\\alpha$.', 'd': [('$\\sin\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = \\sin\\dfrac{\\pi}{2} + \\sin\\alpha = 1 + \\sin\\alpha$, поэтому тождество неверно.', 'Синус суммы не равен сумме синусов.'), ('$\\sin\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = \\cos\\left(\\dfrac{\\pi}{2} - \\left(\\dfrac{\\pi}{2} + \\alpha\\right)\\right) = \\cos(-\\alpha) = -\\cos\\alpha$, поэтому тождество неверно.', 'Косинус — чётная функция: $\\cos(-\\alpha) = \\cos\\alpha$.'), ('$\\sin\\left(\\dfrac{\\pi}{2} + \\alpha\\right) = \\sin\\dfrac{\\pi}{2}\\sin\\alpha + \\cos\\dfrac{\\pi}{2}\\cos\\alpha = \\sin\\alpha$, поэтому тождество неверно.', '$\\sin(x + y) = \\sin x\\cos y + \\cos x\\sin y$: множители перепутаны.')]}, 'G9_TB_27_316_4': {'k': '$\\sin\\left(\\dfrac{3\\pi}{2} - \\alpha\\right) = \\sin\\dfrac{3\\pi}{2}\\cos\\alpha - \\cos\\dfrac{3\\pi}{2}\\sin\\alpha = -1 \\cdot \\cos\\alpha - 0 \\cdot \\sin\\alpha = -\\cos\\alpha$.', 'd': [('$\\sin\\left(\\dfrac{3\\pi}{2} - \\alpha\\right) = \\sin\\dfrac{3\\pi}{2}\\cos\\alpha - \\cos\\dfrac{3\\pi}{2}\\sin\\alpha = 1 \\cdot \\cos\\alpha = \\cos\\alpha$, поэтому тождество неверно.', '$\\sin\\dfrac{3\\pi}{2} = -1$.'), ('$\\sin\\left(\\dfrac{3\\pi}{2} - \\alpha\\right) = \\cos\\dfrac{3\\pi}{2}\\cos\\alpha - \\sin\\dfrac{3\\pi}{2}\\sin\\alpha = \\sin\\alpha$, поэтому тождество неверно.', 'Для синуса разности $\\sin(x - y) = \\sin x\\cos y - \\cos x\\sin y$; применена формула косинуса.'), ('$\\sin\\left(\\dfrac{3\\pi}{2} - \\alpha\\right) = \\sin\\dfrac{3\\pi}{2} - \\sin\\alpha = -1 - \\sin\\alpha$, поэтому тождество неверно.', 'Синус разности не равен разности синусов.')]}, 'G9_TB_27_321_2': {'q': 'Докажите тождество: $\\dfrac{\\sin 2\\alpha + \\sin 4\\alpha}{\\cos 2\\alpha - \\cos 4\\alpha} = \\operatorname{ctg}\\alpha$', 'qwhy': 'в правой части было ctg 2α (ошибка распознавания; с ним тождество неверно); по скану учебника (с. 137, № 321) — ctg α', 'k': '$\\sin 2\\alpha + \\sin 4\\alpha = 2\\sin 3\\alpha\\cos\\alpha$ и $\\cos 2\\alpha - \\cos 4\\alpha = 2\\sin 3\\alpha\\sin\\alpha$, поэтому дробь равна $\\dfrac{\\cos\\alpha}{\\sin\\alpha} = \\operatorname{ctg}\\alpha$.', 'd': [('$\\sin 2\\alpha + \\sin 4\\alpha = 2\\sin 3\\alpha\\cos\\alpha$ и $\\cos 2\\alpha - \\cos 4\\alpha = -2\\sin 3\\alpha\\sin\\alpha$, поэтому дробь равна $-\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\cos x - \\cos y = -2\\sin\\dfrac{x + y}{2}\\sin\\dfrac{x - y}{2}$, а $\\sin\\dfrac{2\\alpha - 4\\alpha}{2} = -\\sin\\alpha$: минусы сокращаются.'), ('$\\sin 2\\alpha + \\sin 4\\alpha = 2\\cos 3\\alpha\\sin\\alpha$ и $\\cos 2\\alpha - \\cos 4\\alpha = 2\\sin 3\\alpha\\sin\\alpha$, поэтому дробь равна $\\operatorname{ctg} 3\\alpha$, поэтому тождество неверно.', '$\\sin x + \\sin y = 2\\sin\\dfrac{x + y}{2}\\cos\\dfrac{x - y}{2}$: синус берётся от полусуммы.'), ('$\\dfrac{\\sin 2\\alpha + \\sin 4\\alpha}{\\cos 2\\alpha - \\cos 4\\alpha} = \\dfrac{\\sin 6\\alpha}{\\cos(-2\\alpha)} = \\dfrac{\\sin 6\\alpha}{\\cos 2\\alpha}$, поэтому тождество неверно.', 'Сумма синусов не равна синусу суммы углов, а разность косинусов — косинусу разности.')]}, 'G9_TB_29_361_1': {'k': '$a_{n+1} - a_{n} = 3 - 4(n + 1) - (3 - 4n) = -4$ — не зависит от $n$, поэтому последовательность — арифметическая прогрессия с разностью $d = -4$.', 'd': 'KEEP'}, 'G9_TB_29_361_2': {'k': '$a_{n+1} - a_{n} = -5 + 2(n + 1) - (-5 + 2n) = 2$ — не зависит от $n$, поэтому последовательность — арифметическая прогрессия с разностью $d = 2$.', 'd': 'KEEP'}, 'G9_TB_29_361_5': {'k': '$a_{n+1} - a_{n} = 3 - 5(n + 1) - (3 - 5n) = -5$ — не зависит от $n$, поэтому последовательность — арифметическая прогрессия с разностью $d = -5$.', 'd': 'KEEP'}, 'G9_TB_30_388': {'k': 'По формуле $S_{n} = \\dfrac{2a_{1} + (n - 1)d}{2} \\cdot n$ имеем $S_{4} = 4a_{1} + 6d$, $S_{8} = 8a_{1} + 28d$, $S_{12} = 12a_{1} + 66d$, а $3(S_{8} - S_{4}) = 3(4a_{1} + 22d) = 12a_{1} + 66d = S_{12}$.', 'd': 'KEEP'}, 'G9_TB_32_409': {'k': '$(x - 1)(x^{n-1} + x^{n-2} + \\ldots + 1) = (x^{n} + x^{n-1} + \\ldots + x) - (x^{n-1} + \\ldots + x + 1)$, и все слагаемые, кроме $x^{n}$ и $-1$, взаимно уничтожаются, т. е. произведение равно $x^{n} - 1$.', 'd': 'KEEP'}, 'G9_TB_6_55': {'k': 'Так как $x_{1}$, $x_{2}$ — нули трёхчлена, $ax_{0}^{2} + bx_{0} + c = a(x_{0} - x_{1})(x_{0} - x_{2})$, поэтому $a(ax_{0}^{2} + bx_{0} + c) = a^{2}(x_{0} - x_{1})(x_{0} - x_{2}) < 0$, так как $a^{2} > 0$, $x_{0} - x_{1} > 0$, $x_{0} - x_{2} < 0$.', 'd': [('$ax_{0}^{2} + bx_{0} + c = a(x_{0} - x_{1})(x_{0} - x_{2})$, а $(x_{0} - x_{1})(x_{0} - x_{2}) > 0$, поэтому $a(ax_{0}^{2} + bx_{0} + c) = a^{2}(x_{0} - x_{1})(x_{0} - x_{2}) > 0$.', 'При $x_{1} < x_{0} < x_{2}$ множители $x_{0} - x_{1} > 0$ и $x_{0} - x_{2} < 0$ разных знаков, и произведение отрицательно.'), ('Между нулями парабола лежит ниже оси $Ox$, поэтому $ax_{0}^{2} + bx_{0} + c < 0$, а значит, и $a(ax_{0}^{2} + bx_{0} + c) < 0$.', 'Ниже оси парабола лежит между нулями только при $a > 0$; при $a < 0$ значение положительно. Знак произведения даёт множитель $a^{2} > 0$.'), ('$ax_{0}^{2} + bx_{0} + c = (x_{0} - x_{1})(x_{0} - x_{2})$, и это отрицательно, поэтому $a(ax_{0}^{2} + bx_{0} + c) < 0$ при $a > 0$.', 'Потерян множитель $a$: $ax^{2} + bx + c = a(x - x_{1})(x - x_{2})$; к тому же случай $a < 0$ не рассмотрен.')]}, 'G9_TB_ТЗГ2_212': {'k': '$2(a^{2} + b^{2} + c^{2} - ab - ac - bc) = (a - b)^{2} + (b - c)^{2} + (c - a)^{2} \\ge 0$, поэтому $a^{2} + b^{2} + c^{2} \\ge ab + ac + bc$.', 'd': [('$a^{2} + b^{2} + c^{2} - ab - ac - bc = a(a - b) + b(b - c) + c(c - a)$, и каждое слагаемое неотрицательно, поэтому неравенство верно.', 'Слагаемые $a(a - b)$ и др. могут быть отрицательными: при $a = 1$, $b = 2$ получаем $-1$.'), ('$2(a^{2} + b^{2} + c^{2} - ab - ac - bc) = (a + b)^{2} + (b + c)^{2} + (c + a)^{2} \\ge 0$, поэтому неравенство верно.', '$(a + b)^{2} + (b + c)^{2} + (c + a)^{2} = 2(a^{2} + b^{2} + c^{2}) + 2(ab + bc + ca)$: знаки при произведениях другие.'), ('При $a = b = c$ обе части равны, а при остальных значениях левая часть больше, поэтому неравенство верно.', 'Утверждение «при остальных значениях левая часть больше» и есть то, что нужно доказать.')]}, 'G9_TB_УКГ2_190': {'k': '$\\dfrac{ac^{2} + b}{c} = ac + \\dfrac{b}{c}$, а для неотрицательных чисел $ac$ и $\\dfrac{b}{c}$ по неравенству о средних $ac + \\dfrac{b}{c} \\ge 2\\sqrt{ac \\cdot \\dfrac{b}{c}} = 2\\sqrt{ab}$.', 'd': [('$\\dfrac{ac^{2} + b}{c} = ac + b$, и по неравенству о средних $ac + b \\ge 2\\sqrt{abc}$, поэтому неравенство верно.', '$\\dfrac{b}{c} \\ne b$; к тому же получилась оценка $2\\sqrt{abc}$, а не $2\\sqrt{ab}$.'), ('$\\dfrac{ac^{2} + b}{c} = ac + \\dfrac{b}{c} \\ge 2\\sqrt{ac} \\cdot \\sqrt{\\dfrac{b}{c}} \\cdot \\dfrac{1}{2} = \\sqrt{ab}$, поэтому неравенство верно.', 'Неравенство о средних: $x + y \\ge 2\\sqrt{xy}$; множитель $\\dfrac{1}{2}$ лишний, и получена более слабая оценка $\\sqrt{ab}$.'), ('$\\dfrac{ac^{2} + b}{c} \\ge \\dfrac{ac^{2}}{c} = ac$, а $ac \\ge 2\\sqrt{ab}$, поэтому неравенство верно.', 'Неравенство $ac \\ge 2\\sqrt{ab}$ неверно в общем случае (например, при $a = 1$, $b = 4$, $c = 1$: $1 < 4$).')]}, 'G9_TB_УКГ2_191': {'k': '$(a + b)\\left(\\dfrac{1}{a} + \\dfrac{1}{b}\\right) = \\dfrac{(a + b)^{2}}{ab}$, а $(a + b)^{2} - 4ab = (a - b)^{2} \\ge 0$, поэтому $\\dfrac{(a + b)^{2}}{ab} \\ge 4$ при $a, b > 0$.', 'd': [('$(a + b)\\left(\\dfrac{1}{a} + \\dfrac{1}{b}\\right) = \\dfrac{(a + b)^{2}}{ab}$, а $(a + b)^{2} \\ge 2ab$, поэтому произведение не меньше $2$.', '$(a + b)^{2} - 4ab = (a - b)^{2} \\ge 0$, т. е. $(a + b)^{2} \\ge 4ab$ — более сильная оценка, дающая $4$.'), ('$(a + b)\\left(\\dfrac{1}{a} + \\dfrac{1}{b}\\right) = 1 + 1 = 2$, так как $a \\cdot \\dfrac{1}{a} = 1$ и $b \\cdot \\dfrac{1}{b} = 1$, поэтому неравенство неверно.', 'При раскрытии скобок получаются четыре слагаемых: $2 + \\dfrac{a}{b} + \\dfrac{b}{a}$.'), ('$(a + b)\\left(\\dfrac{1}{a} + \\dfrac{1}{b}\\right) = \\dfrac{(a + b)^{2}}{ab} > 4$, так как $(a + b)^{2} > 4ab$ при любых положительных $a$, $b$.', 'При $a = b$ имеем $(a + b)^{2} = 4ab$, и выражение равно $4$; строгое неравенство неверно.')]}, 'G9_TB_УКГ2_192': {'k': 'По неравенству о средних $1 + \\dfrac{a^{2}}{bc} \\ge \\dfrac{2a}{\\sqrt{bc}}$ и т. д.; перемножив три неравенства с положительными частями, получаем не меньше $\\dfrac{8abc}{\\sqrt{bc}\\sqrt{ac}\\sqrt{ab}} = 8$.', 'd': [('$1 + \\dfrac{a^{2}}{bc} \\ge \\dfrac{a}{\\sqrt{bc}}$ и т. д., поэтому произведение не меньше $\\dfrac{abc}{abc} = 1$, и неравенство с $8$ не доказано.', 'Неравенство о средних: $1 + x \\ge 2\\sqrt{x}$; множитель $2$ потерян, отсюда $1$ вместо $8$.'), ('Каждый множитель больше $1$, поэтому произведение больше $1 \\cdot 1 \\cdot 1$, т. е. не меньше $8$.', 'Из того, что каждый множитель больше $1$, следует лишь, что произведение больше $1$.'), ('Сложив неравенства $1 + \\dfrac{a^{2}}{bc} \\ge \\dfrac{2a}{\\sqrt{bc}}$ и два аналогичных, получаем, что произведение не меньше $6$.', 'Нужно перемножить неравенства (все части положительны), а не сложить их.')]}, 'G9_TB_УКГ3_323_1': {'k': '$\\cos^{4}\\alpha - \\sin^{4}\\alpha = \\cos 2\\alpha$, поэтому левая часть равна $\\cos 2\\alpha + \\sin 2\\alpha = \\sqrt{2}\\left(\\cos 2\\alpha\\cos\\dfrac{\\pi}{4} + \\sin 2\\alpha\\sin\\dfrac{\\pi}{4}\\right) = \\sqrt{2}\\cos\\left(2\\alpha - \\dfrac{\\pi}{4}\\right)$.', 'd': [('Левая часть равна $\\cos 2\\alpha + \\sin 2\\alpha = \\sqrt{2}\\cos\\left(2\\alpha + \\dfrac{\\pi}{4}\\right)$, поэтому тождество неверно.', '$\\cos\\left(x + \\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}(\\cos x - \\sin x)$; сумме соответствует $\\cos\\left(x - \\dfrac{\\pi}{4}\\right)$.'), ('$\\cos^{4}\\alpha - \\sin^{4}\\alpha = (\\cos^{2}\\alpha - \\sin^{2}\\alpha)^{2} = \\cos^{2} 2\\alpha$, поэтому левая часть равна $\\cos^{2} 2\\alpha + \\sin 2\\alpha$, поэтому тождество неверно.', 'Разность четвёртых степеней равна $(\\cos^{2}\\alpha - \\sin^{2}\\alpha)(\\cos^{2}\\alpha + \\sin^{2}\\alpha) = \\cos 2\\alpha$.'), ('Левая часть равна $\\cos 2\\alpha + \\sin 2\\alpha = \\cos\\left(2\\alpha - \\dfrac{\\pi}{4}\\right)$, поэтому тождество неверно.', '$\\cos\\left(x - \\dfrac{\\pi}{4}\\right) = \\dfrac{\\sqrt{2}}{2}(\\cos x + \\sin x)$: потерян множитель $\\sqrt{2}$.')]}, 'G9_TB_УКГ3_323_2': {'k': '$\\cos\\left(\\dfrac{2\\pi}{3} + \\alpha\\right) + \\cos\\left(\\dfrac{2\\pi}{3} - \\alpha\\right) = 2\\cos\\dfrac{2\\pi}{3}\\cos\\alpha = -\\cos\\alpha$, поэтому левая часть равна $\\cos\\alpha - \\cos\\alpha = 0$.', 'd': [('$\\cos\\left(\\dfrac{2\\pi}{3} + \\alpha\\right) + \\cos\\left(\\dfrac{2\\pi}{3} - \\alpha\\right) = 2\\cos\\dfrac{2\\pi}{3}\\cos\\alpha = \\cos\\alpha$, поэтому левая часть равна $2\\cos\\alpha$, поэтому тождество неверно.', '$\\cos\\dfrac{2\\pi}{3} = -\\dfrac{1}{2}$, поэтому сумма равна $-\\cos\\alpha$.'), ('$\\cos\\left(\\dfrac{2\\pi}{3} + \\alpha\\right) + \\cos\\left(\\dfrac{2\\pi}{3} - \\alpha\\right) = 2\\sin\\dfrac{2\\pi}{3}\\sin\\alpha = \\sqrt{3}\\sin\\alpha$, поэтому левая часть равна $\\cos\\alpha + \\sqrt{3}\\sin\\alpha$, поэтому тождество неверно.', '$\\cos x + \\cos y = 2\\cos\\dfrac{x + y}{2}\\cos\\dfrac{x - y}{2}$: произведение косинусов, а не синусов.'), ('$\\cos\\left(\\dfrac{2\\pi}{3} + \\alpha\\right) + \\cos\\left(\\dfrac{2\\pi}{3} - \\alpha\\right) = \\cos\\dfrac{4\\pi}{3} = -\\dfrac{1}{2}$, поэтому левая часть равна $\\cos\\alpha - \\dfrac{1}{2}$, поэтому тождество неверно.', 'Сумма косинусов не равна косинусу суммы углов.')]}, 'G9_TB_УКГ3_324_1': {'k': 'Числитель $\\sin 2\\alpha + 2\\sin\\alpha\\cos 4\\alpha = 2\\sin\\alpha(\\cos\\alpha + \\cos 4\\alpha)$, знаменатель $\\cos\\alpha + (1 - 2\\sin^{2} 2\\alpha) = \\cos\\alpha + \\cos 4\\alpha$, поэтому дробь равна $2\\sin\\alpha$.', 'd': [('$\\sin 5\\alpha - \\sin 3\\alpha = 2\\cos\\alpha\\sin 4\\alpha$, поэтому числитель равен $\\sin 2\\alpha + 2\\cos\\alpha\\sin 4\\alpha$, и дробь не сводится к $2\\sin\\alpha$, поэтому тождество неверно.', '$\\sin x - \\sin y = 2\\sin\\dfrac{x - y}{2}\\cos\\dfrac{x + y}{2} = 2\\sin\\alpha\\cos 4\\alpha$.'), ('$1 - 2\\sin^{2} 2\\alpha = \\cos 2\\alpha$, поэтому знаменатель равен $\\cos\\alpha + \\cos 2\\alpha$, и дробь не равна $2\\sin\\alpha$, поэтому тождество неверно.', '$1 - 2\\sin^{2} x = \\cos 2x$, и при $x = 2\\alpha$ это $\\cos 4\\alpha$.'), ('Числитель равен $2\\sin\\alpha(\\cos\\alpha + \\cos 4\\alpha)$, знаменатель $\\cos\\alpha + \\cos 4\\alpha$, поэтому дробь равна $2\\sin\\alpha\\cos\\alpha = \\sin 2\\alpha$, поэтому тождество неверно.', 'После сокращения на $\\cos\\alpha + \\cos 4\\alpha$ остаётся $2\\sin\\alpha$; множитель $\\cos\\alpha$ лишний.')]}, 'G9_TB_УКГ3_324_2': {'k': 'Числитель $(\\sin\\alpha + \\sin 7\\alpha) + (\\sin 3\\alpha + \\sin 5\\alpha) = 2\\sin 4\\alpha(\\cos 3\\alpha + \\cos\\alpha)$, знаменатель $(\\cos\\alpha - \\cos 7\\alpha) + (\\cos 5\\alpha - \\cos 3\\alpha) = 2\\sin 4\\alpha(\\sin 3\\alpha - \\sin\\alpha)$, а $\\dfrac{\\cos 3\\alpha + \\cos\\alpha}{\\sin 3\\alpha - \\sin\\alpha} = \\dfrac{2\\cos 2\\alpha\\cos\\alpha}{2\\cos 2\\alpha\\sin\\alpha} = \\operatorname{ctg}\\alpha$.', 'd': [('Числитель равен $2\\sin 4\\alpha(\\cos 3\\alpha + \\cos\\alpha)$, знаменатель $2\\sin 4\\alpha(\\sin 3\\alpha - \\sin\\alpha)$, а $\\dfrac{\\cos 3\\alpha + \\cos\\alpha}{\\sin 3\\alpha - \\sin\\alpha} = \\dfrac{2\\cos 2\\alpha\\cos\\alpha}{2\\sin 2\\alpha\\cos\\alpha} = \\operatorname{ctg} 2\\alpha$, поэтому тождество неверно.', '$\\sin 3\\alpha - \\sin\\alpha = 2\\sin\\alpha\\cos 2\\alpha$: синус берётся от полуразности.'), ('Числитель равен $\\sin 16\\alpha$, знаменатель $\\cos 4\\alpha$, поэтому дробь равна $\\dfrac{\\sin 16\\alpha}{\\cos 4\\alpha}$, поэтому тождество неверно.', 'Сумма синусов не равна синусу суммы углов.'), ('Числитель равен $2\\sin 4\\alpha(\\cos 3\\alpha + \\cos\\alpha)$, знаменатель $2\\cos 4\\alpha(\\sin 3\\alpha - \\sin\\alpha)$, поэтому дробь равна $\\operatorname{tg} 4\\alpha\\operatorname{ctg}\\alpha$, поэтому тождество неверно.', '$\\cos x - \\cos y = -2\\sin\\dfrac{x + y}{2}\\sin\\dfrac{x - y}{2}$: при группировке получается множитель $\\sin 4\\alpha$, а не $\\cos 4\\alpha$.')]}, 'G9_TB_УКГ3_326_3': {'k': '$\\operatorname{tg}\\alpha + \\operatorname{tg}\\beta = \\dfrac{\\sin\\alpha\\cos\\beta + \\cos\\alpha\\sin\\beta}{\\cos\\alpha\\cos\\beta} = \\dfrac{\\sin(\\alpha + \\beta)}{\\cos\\alpha\\cos\\beta}$; при $\\alpha = 99^{\\circ}$, $\\beta = 81^{\\circ}$ числитель $\\sin 180^{\\circ} = 0$, поэтому $\\operatorname{tg} 99^{\\circ} + \\operatorname{tg} 81^{\\circ} = 0$.', 'd': [('Тождество верно, а $\\operatorname{tg} 99^{\\circ}$ не определён, поэтому выражение $\\operatorname{tg} 99^{\\circ} + \\operatorname{tg} 81^{\\circ}$ не определено.', 'Тангенс не определён только при $90^{\\circ} + 180^{\\circ}k$; $\\cos 99^{\\circ} \\ne 0$, и сумма равна $\\dfrac{\\sin 180^{\\circ}}{\\cos 99^{\\circ}\\cos 81^{\\circ}} = 0$.'), ('$\\operatorname{tg} 99^{\\circ} + \\operatorname{tg} 81^{\\circ} = \\operatorname{tg} 180^{\\circ} = 0$ по формуле $\\operatorname{tg}\\alpha + \\operatorname{tg}\\beta = \\operatorname{tg}(\\alpha + \\beta)$.', 'Сумма тангенсов не равна тангенсу суммы; значение $0$ получено из неверной формулы.'), ('$\\operatorname{tg}\\alpha + \\operatorname{tg}\\beta = \\dfrac{\\sin(\\alpha + \\beta)}{\\cos\\alpha\\cos\\beta}$, а $\\cos 99^{\\circ}\\cos 81^{\\circ} = \\cos 180^{\\circ} = -1$, поэтому сумма равна $-\\sin 180^{\\circ} = 0$.', 'Произведение косинусов не равно косинусу суммы; ответ $0$ верен лишь потому, что $\\sin 180^{\\circ} = 0$.')]}, 'G9_TB_УКГ3_332_2': {'k': '$\\operatorname{ctg}\\alpha\\sin\\alpha = \\cos\\alpha$ и $2\\cos^{2}\\alpha + 2\\sin^{2}\\alpha = 2$, поэтому левая часть равна $\\cos\\alpha - 2$.', 'd': [('$\\operatorname{ctg}\\alpha\\sin\\alpha = \\cos\\alpha$, а $2\\cos^{2}\\alpha + 2\\sin^{2}\\alpha = 2\\cos 2\\alpha$, поэтому левая часть равна $\\cos\\alpha - 2\\cos 2\\alpha$, поэтому тождество неверно.', '$\\cos^{2}\\alpha + \\sin^{2}\\alpha = 1$; $\\cos 2\\alpha = \\cos^{2}\\alpha - \\sin^{2}\\alpha$ — разность.'), ('$\\operatorname{ctg}\\alpha\\sin\\alpha = 1$, поэтому левая часть равна $1 - 2 = -1$, поэтому тождество неверно.', '$\\operatorname{ctg}\\alpha\\sin\\alpha = \\dfrac{\\cos\\alpha}{\\sin\\alpha} \\cdot \\sin\\alpha = \\cos\\alpha$.'), ('$\\operatorname{ctg}\\alpha\\sin\\alpha = \\cos\\alpha$ и $2\\cos^{2}\\alpha + 2\\sin^{2}\\alpha = 0$, поэтому левая часть равна $\\cos\\alpha$, поэтому тождество неверно.', '$\\cos^{2}\\alpha + \\sin^{2}\\alpha = 1$, а не $0$.')]}, 'G9_TB_УКГ3_332_3': {'k': '$1 + \\operatorname{tg}^{2}\\alpha = \\dfrac{1}{\\cos^{2}\\alpha}$, поэтому $\\dfrac{3}{1 + \\operatorname{tg}^{2}\\alpha} = 3\\cos^{2}\\alpha$.', 'd': [('$1 + \\operatorname{tg}^{2}\\alpha = \\dfrac{1}{\\sin^{2}\\alpha}$, поэтому левая часть равна $3\\sin^{2}\\alpha$, поэтому тождество неверно.', '$1 + \\operatorname{tg}^{2}\\alpha = \\dfrac{\\cos^{2}\\alpha + \\sin^{2}\\alpha}{\\cos^{2}\\alpha} = \\dfrac{1}{\\cos^{2}\\alpha}$.'), ('$1 + \\operatorname{tg}^{2}\\alpha = \\cos^{2}\\alpha$, поэтому левая часть равна $\\dfrac{3}{\\cos^{2}\\alpha}$, поэтому тождество неверно.', '$1 + \\operatorname{tg}^{2}\\alpha = \\dfrac{1}{\\cos^{2}\\alpha}$: перевёрнута дробь.'), ('$\\dfrac{3}{1 + \\operatorname{tg}^{2}\\alpha} = 3 + \\dfrac{3}{\\operatorname{tg}^{2}\\alpha} = 3 + 3\\operatorname{ctg}^{2}\\alpha$, поэтому тождество неверно.', 'Дробь с суммой в знаменателе нельзя разбить на сумму дробей.')]}}
